/**
 * Reference Arithmetic Calculator
 * Used to verify Krusch sandbox contract execution and 2PC atomic apply.
 */

export function add(a, b) {
  return a + b;
}

export function subtract(a, b) {
  return a - b;
}

export function multiply(a, b) {
  return a * b;
}

export function divide(a, b) {
  if (b === 0) {
    throw new Error('Division by zero');
  }
  return a / b;
}

export function power(base, exp) {
  return Math.pow(base, exp);
}

export function modulo(a, b) {
  if (b === 0) {
    throw new Error('Modulo by zero');
  }
  return a % b;
}

export function clamp(val, min, max) {
  return Math.min(Math.max(val, min), max);
}

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { add, subtract, multiply, divide, power, modulo, clamp } from '../src/calculator.js';

describe('Calculator Operations', () => {
  it('correctly adds numbers', () => {
    assert.equal(add(2, 3), 5);
    assert.equal(add(-5, 5), 0);
  });

  it('correctly subtracts numbers', () => {
    assert.equal(subtract(10, 4), 6);
  });

  it('correctly multiplies numbers', () => {
    assert.equal(multiply(6, 7), 42);
  });

  it('correctly divides numbers and guards zero-division', () => {
    assert.equal(divide(100, 4), 25);
    assert.throws(() => divide(10, 0), /Division by zero/);
  });

  it('correctly computes exponentiation', () => {
    assert.equal(power(2, 8), 256);
  });

  it('correctly computes modulo and guards zero-division', () => {
    assert.equal(modulo(14, 3), 2);
    assert.throws(() => modulo(5, 0), /Modulo by zero/);
  });

  it('correctly clamps numbers within range', () => {
    assert.equal(clamp(15, 0, 10), 10);
    assert.equal(clamp(-5, 0, 10), 0);
    assert.equal(clamp(7, 0, 10), 7);
  });
});
